  const artwork=(label,color)=>'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="320" height="220" viewBox="0 0 320 220"><rect width="320" height="220" fill="${color}"/><circle cx="270" cy="30" r="100" fill="#fff" opacity=".25"/><rect x="120" y="48" width="80" height="105" rx="18" fill="#fff" opacity=".75"/><path d="M135 77h50M135 92h50M135 107h32" stroke="#008c82" stroke-width="5" stroke-linecap="round"/><text x="160" y="190" text-anchor="middle" font-family="Arial" font-size="18" fill="#235a57">${label}</text></svg>`);
  const products=[['qa-product-1','QA · Café especial',15,'#d9ede4'],['qa-product-2','QA · Suco natural',10,'#fff0cf'],['qa-product-3','QA · Chocolate artesanal',12,'#f1dfd7'],['qa-product-4','QA · Combo da tarde',24,'#e2e4ff']].map(([id,name,price,color])=>({productId:id,productName:name,salePrice:price,category:'QA',itemKind:'product',productImage:artwork('Produto QA',color)}));
