  const data={catalogOrders:[order('a01','recebido',4),order('a02','preparando',18,{serviceModeType:'delivery',serviceModeLabel:'Entrega',customerLocation:'Endereço fictício QA'}),order('a03','separando',35),order('a04','entregue',85,{deliveredAt:new Date(now-70*60000).toISOString()}),order('a05','cancelado',100),order('a06','expirado',120,{expiredAt:new Date(now-90*60000).toISOString()}),order('b01','recebido',5,{spaceId:'qa-b',spaceName:spaces[1].name,customerName:'Cliente QA · espaço B'}),{...order('historico','recebido',3000),schemaVersion:1,source:'online_catalog',customerName:'Histórico QA somente leitura'}],clientes:[],vendas:[]};
  const stores=new Map(spaces.map((s,i)=>[s.id,{id:s.id,slug:i?'ux-qa-b':'ux-qa-a',revision:1,published:!i,selectedProductIds:products.map(p=>p.productId),catalogSettings:{publicName:i?'Loja QA · espaço B':'Loja QA · Adi festa',welcomeText:'Marca e produtos fictícios para conferir a nova interface.',primaryColor:'#009f95',secondaryColor:'#153b46',pickupEnabled:true,paymentMethods:['pix','dinheiro'],checkoutEnabled:!i},presentation:{products:{}}}]));
